import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.BXzK3EA4.js";const d="/assets/image%20(31).AiKXYyf3.png",i="/assets/image%20(32).DJVyE9Dn.png",n="/assets/image%20(26).Dgzn1dSq.png",u=JSON.parse('{"title":"Download & Install Library","description":"","frontmatter":{},"headers":[],"relativePath":"trading-platform/metatrader-5/download-and-install-library.md","filePath":"trading-platform/metatrader-5/download-and-install-library.md"}'),l={name:"trading-platform/metatrader-5/download-and-install-library.md"};function s(p,e,c,h,m,g){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="download-install-library" tabindex="-1">Download &amp; Install Library <a class="header-anchor" href="#download-install-library" aria-label="Permalink to &quot;Download &amp; Install Library&quot;">​</a></h1><p><strong>Download the MQL5 Libray and Unzip it</strong></p><p><a href="../../.gitbook/assets/Tradeboard.zip">Download File</a></p><p><strong>Open MQL5 -&gt; File -&gt; Open DataFolder as shown below</strong></p><figure><img src="'+d+'" alt=""><figcaption></figcaption></figure><p><strong>Navigate to \\MQL5\\Include folder and paste the Unzipped Tradeboard Folder here as shown below</strong></p><figure><img src="'+i+'" alt=""><figcaption></figcaption></figure><p>Now the Installation Process is completed if you open MetaEditor you should see the Folders with Library Files as shown below</p><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p>The <code>Tradeboard</code> folder contains four files:</p><ul><li><code>TradeboardApi.mqh</code> - the six order functions. This is the only file you include.</li><li><code>CommonDefs.mqh</code> - the <code>Exchanges</code>, <code>ProductTypes</code> and <code>PriceTypes</code> enums.</li><li><code>UrlParser.mqh</code> - splits your Tradeboard URL into host, path and port.</li><li><code>WinINet.mqh</code> - the HTTP transport, built on <code>wininet.dll</code>.</li></ul><p>Put the folder at <code>MQL5\\Include\\Tradeboard</code>, so the full path to the main file is <code>MQL5\\Include\\Tradeboard\\TradeboardApi.mqh</code>. That matches the <code>#include &lt;Tradeboard/TradeboardApi.mqh&gt;</code> line used on the next page. If MetaEditor was already open, close and reopen it so it picks up the new include folder.</p><p>Because <code>WinINet.mqh</code> imports <code>wininet.dll</code> and <code>kernel32.dll</code>, every EA built on this library needs <strong>Allow DLL imports</strong> enabled. Set it per EA in the Common tab of the EA properties dialog, or globally under Tools, Options, Expert Advisors.</p>',13)])])}const b=o(l,[["render",s]]);export{u as __pageData,b as default};
